package cl.bcs.filters.adapter.out.jdbc;

import cl.bcs.filters.port.out.SsoStateRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;

/**
 * Persists SSO CSRF state tokens in a DB table so they survive pod restarts
 * and load-balanced deployments (no sticky session requirement).
 *
 * Expired entries (> 10 min) are pruned on each store call to keep the table small.
 *
 * RULE-046: state is always a UUID generated by the caller — never hardcoded.
 */
@Repository
class SsoStateJdbcAdapter implements SsoStateRepository {

    private static final int STATE_TTL_MINUTES = 10;

    private final JdbcTemplate jdbc;

    SsoStateJdbcAdapter(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public void storeState(String state) {
        // Prune stale entries first
        jdbc.update("DELETE FROM SSO_STATE WHERE CREATED_AT < ?",
                LocalDateTime.now().minusMinutes(STATE_TTL_MINUTES));
        jdbc.update("INSERT INTO SSO_STATE (STATE_KEY, CREATED_AT) VALUES (?, ?)",
                state, LocalDateTime.now());
    }

    @Override
    public boolean validateAndConsumeState(String state) {
        LocalDateTime cutoff = LocalDateTime.now().minusMinutes(STATE_TTL_MINUTES);
        int deleted = jdbc.update(
                "DELETE FROM SSO_STATE WHERE STATE_KEY = ? AND CREATED_AT >= ?",
                state, cutoff);
        return deleted > 0;
    }
}
